// app/page.tsx
import { createClient } from '@supabase/supabase-js';

export default async function Home() {
  // 创建 Supabase 客户端
  const supabase = createClient(
    process.env.NEXT_PUBLIC_SUPABASE_URL!,
    process.env.NEXT_PUBLIC_SUPABASE_ANON_KEY!
  );

  // 从 papers 表获取所有数据
  const { data: papers, error } = await supabase.from('papers').select('*');

  // 如果发生错误，可以在控制台查看
  if (error) {
    console.error('数据库查询失败:', error.message);
  }

  return (
    <div className="p-8">
      <h1 className="text-2xl font-bold">POWER 论文列表</h1>
      
      {/* 渲染逻辑 */}
      {papers?.length === 0 ? (
        <p className="text-gray-500">暂无论文，请稍后再试。</p>
      ) : (
        papers?.map((paper) => (
          <div key={paper.id} className="mt-4 p-4 border rounded bg-white">
            <h2 className="text-xl font-semibold">{paper.title}</h2>
            <p><strong>作者：</strong>{paper.author}</p>
            <p><strong>摘要：</strong>{paper.abstract.substring(0, 100)}...</p>
            <p><strong>关键词：</strong>{paper.keywords?.join(', ')}</p>
          </div>
        ))
      )}
    </div>
  );
}